import os, re

def load_grids():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows_raw = t[m.end():].split('\n')[:h]
        if len(rows_raw) == h and all(len(row) == w for row in rows_raw):
            rows = [row.split() for row in rows_raw]
            if all(all(x.isdigit() for x in row) for row in rows):
                G[k] = [[int(x) for x in row] for row in rows]
    return G, sorted(G.keys())

G, keys = load_grids()
